urlset:
{% for page in pages %}

    {{ page.loc }}
    {% if page.lastmod %}{{ page.lastmod }}{% endif %}
    {{ page.priority }}
    {{ page.changefreq or 'weekly' }}
    {% for img in page.images or [] %}

        {{ img.loc }}
        {% if img.caption %}{{ img.caption }}{% endif %}

    {% endfor %}

{% endfor %}
